import java.util.*;
import java.util.concurrent.*;

class NotEnoughItemsException extends Exception { }

public class Locker {
    private final int id;
    private final Object lock = new Object();
    private int count;

    public Locker(int id, int count) { 
        this.id = id;
        this.count = count;
    }

    public void moveParcel(Locker toLocker, int quantity, long timeout, TimeUnit timeUnit) throws InterruptedException, ExecutionException, TimeoutException {
        if (toLocker == null || quantity <= 0 || quantity > this.count || Thread.currentThread().getId() == toLocker.id) throw new IllegalArgumentException();

        long startTime = System.nanoTime();
        while(true) {
            // try acquiring locks on both lockers, with a random delay before retrying the first lock acquisition.
            if (Thread.currentThread().getId() != this.id && !lockAcquiredWithDelay(this)) return;

            if (toLocker.count + quantity <= toLocker.count) throw new NotEnoughItemsException(); // Throw an exception if there are not enough items in the target locker

            if (Thread.currentThread().getId() != this.id && !lockAcquiredWithDelay(toLocker)) return;

            synchronized (this) {
                if(this.count >= quantity){ 
                    // If source locker has enough items, move the parcel and decrease the count
                    toLocker.count += quantity;
                    this.count -= quantity;
                    System.out.println("Parcels moved from Locker " + this.id + " to Locker " + toLocker.id);
                } else { 
                    throw new NotEnoughItemsException();
                }
            }

            if(System.nanoTime() - startTime >= timeUnit.toNanos(timeout)) return; // Return if timeout elapses
        }
    }

    private boolean lockAcquiredWithDelay(Locker locker) {
        try { Thread.sleep((long)(Math.random() * 100)); } catch (Exception e) {}

        long startTime = System.nanoTime();
        while(!locker.lock.waitFor(5, TimeUnit.SECONDS)) { // Wait for lock to be released or timeout
            if(System.nanoTime() - startTime >= 500000000) return false; // Return if timeout elapses
        }

        locker.lock.wait();
        return true;
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException, ExecutionException, TimeoutException {
        Locker locker1 = new Locker(1, 20);
        Locker locker2 = new Locker(2, 30);

        locker1.moveParcel(locker2, 5, 3, TimeUnit.SECONDS); // Move 5 parcels from locker 1 to locker 2 with a timeout of 3 seconds
    }
}

import java.util.concurrent.*;

class NotEnoughItemsException extends Exception {
    public NotEnoughItemsException(String message) {
        super(message);
    }
}

class ParcelCount {
    private int count;

    ParcelCount() {
        this.count = 0;
    }

    void addParcel() {
        synchronized (this) {
            count++;
        }
    }

    void removeParcel() throws NotEnoughItemsException {
        if(count == 0) {
            throw new NotEnoughItemsException("Not enough items");
        }
        synchronized (this) {
            count--;
        }
    }
}

class Locker {
    private ReentrantLock lock = new ReentrantLock();
    ParcelCount parcelCount;

    Locker(ParcelCount parcelCount) {
        this.parcelCount = parcelCount;
    }

    void move(Locker target, int quantity, long timeout, TimeUnit unit) throws NotEnoughItemsException, InterruptedException {
        if (!lock.tryLock(timeout, unit)) return false; 

        try {
            target.lock.lock(); // Attempt to lock the target locker
            if (parcelCount.count < quantity) throw new NotEnoughItemsException("Not enough items");

            for(int i = 0; i<quantity; i++) parcelCount.removeParcel();
        } finally {
            lock.unlock(); // Release the source locker regardless of whether the move succeeded
        }
    }
}

public class Main {
    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(3);

        ParcelCount parcelCount = new ParcelCount();
        Locker sourceLocker = new Locker(parcelCount);
        Locker targetLocker = new Locker(parcelCount);

        for (int i=0;i<100;i++) {
            executor.execute(() -> {
                try {
                    Thread.sleep((long)(Math.random() * 1e3)); // Random pause
                    sourceLocker.move(targetLocker, 1, 5, TimeUnit.SECONDS);
                } catch (InterruptedException | NotEnoughItemsException e) {
                    e.printStackTrace();
                }
            });
        }

