import java.util.concurrent.*;
import java.time.*;

public class Main {
    public static void main(String[] args) {
        final ParcelCount source = new ParcelCount();
        final ParcelCount target = new ParcelCount();
        ExecutorService executorService = Executors.newFixedThreadPool(3);

        executorService.execute(() -> {
            try {
                if (!moveParcels(source, target, 10, Duration.ofSeconds(2), TimeUnit.SECONDS))
                    System.out.println("Failed to move parcels.");
            } catch (NotEnoughItemsException e) {
                System.out.println("Not enough items in source locker.");
            }
        });

        executorService.shutdown();
    }

    private static boolean moveParcels(final ParcelCount source, final ParcelCount target, int quantity, Duration timeout, TimeUnit timeUnit) throws NotEnoughItemsException {
        final long deadline = System.nanoTime() + timeUnit.toNanos(timeout.getSeconds());

        while (true) {
            if (source.tryLock()) {
                try {
                    Thread.sleep((int) (Math.random() * 1000)); // random delay before trying to lock target locker

                    if (target.tryLock(deadline, TimeUnit.NANOSECONDS)) {
                        if (source.count > quantity) {
                            source.release();
                            return true;
                        } else {
                            throw new NotEnoughItemsException("Not enough items in source locker.");
                        }
                    }
                } catch (InterruptedException e) {
                    // ignore and try again
                } finally {
                    source.unlock();
                }
            }

            if (System.nanoTime() > deadline)
                return false;
        }
    }

    static class ParcelCount extends ReentrantLock implements java.io.Serializable {
        int count = 0;

        public boolean tryLock(long timeout, TimeUnit unit) throws InterruptedException {
            return super.tryLock(timeout, unit);
        }

        @Override
        public void lock() {
            super.lock();
            count++;
        }

        @Override
        public void unlock() {
            super.unlock();
            count--;
        }
    }

    static class NotEnoughItemsException extends RuntimeException {
        public NotEnoughItemsException(String message) {
