    static boolean moveWidgetsBetweenBins(Bin source, Bin target, int numWidgetsToMove, long timeoutDuration, TimeUnit timeUnit) {
        Duration fixedDelay = Duration.ofMillis(10); // 10ms delay for the fixed pattern

