public class WidgetMover {
    private static final int MAX_THREADS = 3; // The maximum number of threads in the program, including the main thread.
    private static ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);
    private Lock sourceLock = new ReentrantLock();
    private Lock targetLock = new ReentrantLock();

    // Inner class representing a bin.
    private static class Bin {
        private int widgetCount;

        public Bin(int widgets) {
            this.widgetCount = widgets;
        }

        public synchronized void moveWidgets(Bin other, int count) throws NotEnoughWidgetsException {
            if (this.widgetCount < count) throw new NotEnoughWidgetsException("Not enough widgets in source bin.");

            // Acquire the locks for both bins with a delay and retry pattern.
            try {
                boolean gotSourceLock = sourceLock.tryLock(getDelay(), TimeUnit.MILLISECONDS);
                if (!gotSourceLock) throw new InterruptedException("Timeout acquiring lock on source bin.");

                boolean gotTargetLock = targetLock.tryLock(getRandomDelay(), TimeUnit.MILLISECONDS);
                if (!gotTargetLock) {
                    // If the target lock could not be acquired, try again after a random delay.
                    Thread.sleep(getRandomDelay());
                    gotTargetLock = targetLock.tryLock();
                    if (!gotTargetLock) throw new InterruptedException("Timeout acquiring lock on target bin.");
                }
            } catch (InterruptedException e) {
                // If the locks couldn't be acquired, return false to indicate that it failed.
                return; 
            }

            try {
                other.widgetCount += count;
                this.widgetCount -= count;
            } finally {
                sourceLock.unlock();
                targetLock.unlock();
            }
        }
    }

    // Inner class representing the custom exception for when there are not enough widgets in a bin.
    private static class NotEnoughWidgetsException extends Exception {
        public NotEnoughWidgetsException(String msg) { super(msg); }
    }

    // Calculates and returns a random delay component to be used before retrying the lock acquisition.
    private static int getRandomDelay() {
        return (int)(Math.random() * 1000); // Generate a random delay between 0 and 1 second.
    }

    // Calculates and returns a fixed delay component to be used before retrying the lock acquisition.
    private static int getDelay() {
        return 50; // Fixed delay of 50 milliseconds.
    }

    public static void main(String[] args) throws InterruptedException {
        Bin bin1 = new Bin(10);
        Bin bin2 = new Bin(15);

        executor.execute(() -> moveWidgetsBetweenBins(bin1, bin2, 3));
        executor.execute(() -> moveWidgetsBetweenBins(bin2, bin1, 4));
    }

    // A method to perform the moving of widgets between bins.
    private static void moveWidgetsBetweenBins(Bin source, Bin target, int count) {
