            source.moveWidgets(target, count);
            System.out.println("Moved " + count + " widgets from bin " + source.widgetCount + 
                               " to bin " + target.widgetCount);

        } catch (NotEnoughWidgetsException e) {
            // If there weren't enough widgets in the source bin, print an error message and return.
            System.out.println("Error: " + e.getMessage()); 
        } 
    }
}
