class Bin {
    private ReentrantLock lock = new ReentrantLock();
    private WidgetCount widgetCount = new WidgetCount();

    public boolean tryLock(ReentrantLock lock, long timeout) throws InterruptedException {
        return lock.tryLock(timeout, TimeUnit.MILLISECONDS);
    }

    public synchronized boolean lockAndValidate(Bin otherBin, int numberOfWidgetsToMove, long timeoutDuration) throws NotEnoughWidgetsException, InterruptedException {
        if (tryLock(lock, 0)) { // Try to acquire source bin lock immediately
            Thread.sleep(100); // Random delay before retrying the target lock

