            if (success) {
                try {
                    return otherBin.tryLock(lock, timeoutDuration); 
                } catch (InterruptedException e) {
                    lock.unlock(); // Unlock the source bin after failing to acquire target bin lock within time limit
                    throw e;
                }
            } else {
                lock.unlock(); // Unlock the source bin immediately if not enough widgets
            }
        }

        return false;
    }

    public void move(int numberOfWidgetsToMove, Bin otherBin) throws NotEnoughWidgetsException, InterruptedException {
        lock.lockInterruptibly(); // Acquire source bin lock interruptibly

        if (numberOfWidgetsToMove > widgetCount.get()) {
            throw new NotEnoughWidgetsException("Not enough widgets in the bin");
        } else {
            Thread.sleep(100); // Random delay before retrying to acquire target bin lock

            if (otherBin.lockAndValidate(this, numberOfWidgetsToMove, TimeUnit.SECONDS.toMillis(10))) {
                widgetCount.decrement(numberOfWidgetsToMove); // Decrease the count in source bin
                otherBin.widgetCount.increment(numberOfWidgetsToMove); // Increase the count in target bin

                lock.unlock(); 
                otherBin.lock.unlock(); // Unlock both bins after successful move
            } else {
                lock.unlock(); 
            }
        }
    }
}

class NotEnoughWidgetsException extends Exception {
    public NotEnoughWidgetsException(String message) {
        super(message);
    }
}
