// Enum for constellations
enum Constellation {
    CANCER, LEO, TAURUS;
}

// Enum for resonances
enum Resonance {
    NEUTRAL, COLD, WARM;
}

class Runes implements Comparable<Runes> {
    Constellation constellation;
    Resonance resonance;

    Runes(Constellation c, Resonance r) {
        this.constellation = c;
        this.resonance = r;
    }

    @Override
    public int compareTo(Runes o) {
        return constellation == o.constellation ? resonance.compareTo(o.resonance) : constellation.compareTo(o.constellation);
    }
}

class Harmony {
    List<Runes> runes;

    public Harmony(List<Runes> r) {
        this.runes = r;
    }
}

class Grimoire {
    BlockingQueue<Runes> queue;

    public Grimoire() {
        queue = new LinkedBlockingQueue<>();
    }

    public synchronized void channelTheGrimoire(Collection<Runes> runeCollection) {
        for (Runes r : runeCollection) {
            queue.add(r);
        }

        ThreadPoolExecutor executor = new ThreadPoolExecutor(2, 3, 0L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<>());
        while (!queue.isEmpty()) {
            List<Runes> batch = new ArrayList<>();

            for (int i = 0; i < 2 && !queue.isEmpty(); ++i) {
                batch.add(queue.poll());
            }

            executor.execute(() -> {
                Harmony harmony = findHarmonies(batch);

                if (harmony != null) {
                    System.out.println("Harmonized: " + harmony);
                } else {
                    queue.addAll(batch); // Restore the runes to queue
                }
            });
        }

        executor.shutdown();

        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.DAYS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Restore interrupted status
        }
    }

    private Harmony findHarmonies(List<Runes> runeBatch) {
        Set<Runes> usedRune = new HashSet<>();

        for (int i = 0; i < runeBatch.size(); ++i) {
            Runes r1 = runeBatch.get(i);

            if (!usedRune.contains(r1)) {
                for (int j = i + 1; j < runeBatch.size(); ++j) {
                    Runes r2 = runeBatch.get(j);

                    // Check harmony conditions
                    if (r1.constellation == r2.constellation && r1.resonance != r2.resonance) {
                        return new Harmony(Arrays.asList(r1, r2));
