    public Resonance getResonance() { return resonance; }
}

// Class to represent the Grimoire
class Grimoire {
    private final ConcurrentLinkedQueue<Rune> runeQueue = new ConcurrentLinkedQueue<>();  // Queue of runes
    private final ExecutorService executor = Executors.newFixedThreadPool(2);  // Fixed Thread pool with at most 2 threads

    public void channelTheGrimoire(Collection<Rune> candidateRunes) {
        // Transmute the runes using a custom comparator that sequences them first by constellation and then by resonance
        Comparator<Rune> runeComparator = (r1, r2) -> {
            int constellationOrder = r1.getConstellation().compareTo(r2.getConstellation());

            // If the constellations are same, compare resonances in opposite direction 
            if (constellationOrder == 0) {
                return -r1.getResonance().compareTo(r2.getResonance());
            } else {
                return constellationOrder;
            }
        };

        // Queue the runes for processing and harmonizing
        candidateRunes.forEach(rune -> runeQueue.add(rune));

        while (!runeQueue.isEmpty()) {
            Rune r1 = runeQueue.poll();

            executor.execute(() -> {  // Using executor to perform processing of runes in parallel
                List<Rune> possibleMatchingRunes = new ArrayList<>();

                while (!runeQueue.isEmpty()) {
                    Rune r2 = runeQueue.poll();

                    if (runeComparator.compare(r1, r2) == 0 && r1.getResonance() != r2.getResonance()) {  // If the constellations are same and resonances are opposite
                        possibleMatchingRunes.add(new Harmony(r1, r2));
                    } else {
                        runeQueue.offer(r2);  // Offer back to queue as we cannot match it yet
                        break;
                    }
                }

                if (!possibleMatchingRunes.isEmpty()) {  // If there are any matching runes, add them into the queue
                    synchronized (this) {  // Using synchronization to avoid data sharing between threads
                        possibleMatchingRunes.forEach(harmony -> runeQueue.add(harmony));
                    }
                } else {
                    synchronized (this) {  // If no matching rune found, add the single rune back into the queue
                        runeQueue.offer(r1);
                    }
                }
            });
        }

        executor.shutdown();  // Wait for all threads to finish processing and harmonizing
    }
}

public class Main {
    public static void main(String[] args) {
        List<Rune> runes = Arrays.asList(
            new Rune(Constellation.MERCURY, Resonance.POSITIVE),  // Mercury Positive Rune
            new Rune(Constellation.VENUS, Resonance.NEGATIVE),  // Venus Negative Rune
