private static Collection<Animal> createSampleAnimals(int count) {
List<Animal> list = new ArrayList<>();
Random rand = new Random();
Species[] speciesArray = Species.values();
Gender[] genders = Gender.values();

for (int i = 0; i < count; i++) {
Animal animal = new Animal();
animal.species = speciesArray[rand.nextInt(speciesArray.length)];
animal.gender = genders[rand.nextInt(genders.length)];
list.add(animal);
}

return list;
}

