/**
* DelegatingVehicleTracker
* Tracks vehicle locations using a thread-safe ConcurrentHashMap.
* Modified to use explicit Threads for JPF compatibility.
*/
public class DelegatingVehicleTracker {
private final ConcurrentMap<String, Point> locations;
private final Map<String, Point> unmodifiableMap;

public DelegatingVehicleTracker(Map<String, Point> points) {
locations = new ConcurrentHashMap<>(points);
unmodifiableMap = Collections.unmodifiableMap(locations);
}

public Map<String, Point> getLocations() {
return unmodifiableMap;
}

public Point getLocation(String id) {
return locations.get(id);
}

public void setLocation(String id, int x, int y) {
if (locations.replace(id, new Point(x, y)) == null)
throw new IllegalArgumentException("Invalid vehicle ID: " + id);
}

public Map<String, Point> getLocationsAsStatic() {
return Collections.unmodifiableMap(new HashMap<>(locations));
}

public static void main(String[] args) throws InterruptedException {
Map<String, Point> initialLocations = new HashMap<>();
initialLocations.put("V1", new Point(0, 0));
initialLocations.put("V2", new Point(10, 10));
initialLocations.put("V3", new Point(20, 20));

DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initialLocations);

// Reduce thread count and iterations to shorten JPF testing time
Thread[] threads = new Thread[2]; // fewer threads

for (int i = 0; i < 2; i++) {
final int threadId = i;
threads[i] = new Thread(() -> {
Random rand = new Random();
for (int j = 0; j < 3; j++) { // fewer iterations
String vehicleId = "V" + ((threadId % 3) + 1);
int newX = rand.nextInt(21); // 0 to 20
int newY = rand.nextInt(21); // 0 to 20
System.out.println("Thread-" + threadId + ": Setting " + vehicleId + " to (" + newX + ", " + newY + ")");
tracker.setLocation(vehicleId, newX, newY);
try {
Thread.sleep(20); // shorter sleep to speed up execution
} catch (InterruptedException e) {
Thread.currentThread().interrupt();
}
}
});
}

for (Thread t : threads) {
t.start();
}

for (Thread t : threads) {
t.join();
}

System.out.println("\nFinal vehicle locations:");
for (Map.Entry<String, Point> entry : tracker.getLocations().entrySet()) {
System.out.println(entry.getKey() + " => " + entry.getValue());
}
}
}

