import java.util.stream.Collectors;

public class CelestialCaravanTracker {
    private final Map<String, Starlight> havens;
    private static final AtomicInteger counter = new AtomicInteger(0);

    public CelestialCaravanTracker(Map<String, Starlight> initialHavens) {
        this.havens = new ConcurrentHashMap<>();
        initialHavens.forEach((k, v) -> havens.putIfAbsent(k, v));
    }

    public Map<String, Starlight> getHavens() {
        return Collections.unmodifiableMap(havens);
    }

    public Starlight getHaven(String glyph) {
        return havens.getOrDefault(glyph, null);
    }

    public void setHaven(String glyph, int shimmer, int pulse) throws IllegalArgumentException{
        if (!havens.containsKey(glyph)) throw new IllegalArgumentException("Beast does not exist");
        havens.replace(glyph, new Starlight(shimmer, pulse));
    }

    public Map<String, Starlight> getHavensAsStatic() {
        return Collections.unmodifiableMap(havens);
    }

    public static void main(String[] args) throws Exception{
        ExecutorService executor = Executors.newFixedThreadPool(6);

        Map<String, Starlight> initialHavens = new ConcurrentHashMap<>();
        for (int i=0; i < 1000; i++) {
            String glyph = "beast" + counter.incrementAndGet();
            initialHavens.put(glyph, new Starlight(i, i));
        }

        Supplier<CelestialCaravanTracker> supplier = () -> new CelestialCaravanTracker(initialHavens);
        for (int i=0; i < 1000; i++) {
            executor.submit(() -> {
                CelestialCaravanTracker tracker = supplier.get();
                System.out.println("Glyphs: " + tracker.getHavensAsStatic().entrySet());
            });
        }

        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.MINUTES);
    }
}

