class Hoard implements Comparable<Hoard> {
    private int identityHashCode;
    private ArrayList<GemAmount> gems = new ArrayList<>();

    public Hoard(int hashCode) {
        this.identityHashCode = hashCode;
    }

    public void addGem(GemAmount gem) {
        synchronized (gem) {
            if (!gems.contains(gem)) {
                gems.add(gem);
            }
        }
    }

    @Override
    public int compareTo(Hoard other) {
        return Integer.compare(identityHashCode, other.identityHashCode);
    }
}

class GemAmount implements Comparable<GemAmount> {
    private int quantity;

    public GemAmount(int qty) {
        this.quantity = qty;
    }

    @Override
    public int compareTo(GemAmount other) {
        return Integer.compare(this.quantity, other.quantity);
    }
}

class TransferException extends Exception {
    public TransferException(String message) {
        super(message);
    }
}

class Transaction implements Runnable {
    private Hoard from;
    private Hoard to;
    private GemAmount amount;

    public Transaction(Hoard from, Hoard to, GemAmount amount) throws TransferException {
        if (from.compareTo(to) == 0 && !from.equals(to)) { // Same hash code but different objects
            throw new TransferException("Same hash code but different hoards!");
        }
        this.from = from;
        this.to = to;
        this.amount = amount;
    }

    @Override
    public void run() {
        synchronized (from) {
            if (from.gems.contains(amount)) { // If gem exists in source hoard
                from.gems.remove(amount); 
                synchronized (to) { // Ensure order of locks
                    to.addGem(new GemAmount(amount.quantity)); // Add to destination hoard
                }
            } else {
                throw new TransferException("Insufficient gems in source hoard!");
            }
        }
    }
}

