class CrystalCarousel {
    private int capacity;
    private ArrayList<Crystal> carousel = new ArrayList<>();
    private Semaphore availableSlots = new Semaphore(0);  // 0 because initially no slots are available
    private Semaphore totalSlots = new Semaphore(0);       // 0 because initially no slots have been created

    public CrystalCarousel(int capacity) {
        this.capacity = capacity;
        this.carousel = new ArrayList<>(Collections.nCopies(capacity, null));
        totalSlots.release(capacity);   // release all slots at once
    }

    public synchronized void put(Crystal x) throws InterruptedException {
        availableSlots.acquire();  // wait until a slot is available
        carousel.set(getNextIndex(), x);   // insert into carousel
    }

    public synchronized Crystal take() throws InterruptedException {
        while (carousel.contains(null)) {   // loop until a crystal is taken out
            availableSlots.release();       // free the slot if it's been freed by another thread
            availableSlots.acquire();       // wait until a slot becomes available again
        }
        Crystal result = carousel.get(getNextIndex());  // remove from carousel
        carousel.set(getNextIndex(), null);
        return result;
    }

    public synchronized boolean isEmpty() {
        for (Crystal x: carousel)
            if (x != null)
                return false;
        return true;
    }

    private int getNextIndex() {
        try {  // prevent deadlock by not acquiring totalSlots if it's currently being released
            availableSlots.acquire();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new AssertionError(e);
        }
        return carousel.indexOf(null);   // find the index of the first null spot
    }
}

