        } else {
            x.setInLoop();
        }
    }

    public synchronized Potion take() throws InterruptedException {
        if (potionQueue.isEmpty()) {
            availablePotionsSemaphore.release(); // This might block because of the capacity of ArrayBlockingQueue.
            openSlotSemaphore.release();
            return potionQueue.take(); // This will not block because the queue is not empty, it's a blocking operation by itself.
        } else {
            return potionQueue.poll(10, TimeUnit.SECONDS); // This might throw an exception after 10 seconds if no element was added to the queue.
        }
    }

    public boolean isEmpty() {
        return potionQueue.isEmpty();
    }

    public boolean isFull() {
