        this.constellation = new Constellation<>(new HashMap<>());
        if (constellation != null) {
            for (Map.Entry<String, MutableOrb> entry : constellation.map.entrySet()) {
                this.constellation.map.put(entry.getKey(), new MutableOrb(entry.getValue().shimmerX, entry.getValue().shimmerY)); 
