            final String key = constellation.map.keySet().stream()
                    .filter(k -> k.equalsIgnoreCase(sigil))
                    .findFirst().orElse(null);

            if (key != null) {
                return new MutableOrb(constellation.map.get(key).shimmerX, constellation.map.get(key).shimmerY);
