      } finally {
        signal(to.condition);
      }
    });

    executor.shutdown(); // end thread pool after both locks have been acquired

    try {
      future1.get();
      future2.get();

      return true;
    } catch (Exception e) {
      return false;
    } 
  }

  private static void lock(ReentrantLock lock, long timeout, TimeUnit timeUnit) throws InterruptedException {
    // calculate a random delay and add it to the total timeout
    Thread.sleep((long) (Math.random() * (timeUnit.toMillis(timeout) / 2)));

    if (!lock.tryLock(timeout, timeUnit)) {
