        return tryTransfer(dest, amount, timeoutMillis, unit);
    }

    private boolean tryTransfer(Account dest, double amount, long timeoutMillis, TimeUnit unit) {
        if (amount <= 0 || Double.compare(this.balance.get(), amount) < 0) {
            throw new InsufficientFundsException();
        }

        boolean acquired = lock.tryLock(timeoutMillis, unit);
