public class BoundedBuffer {
    private final int capacity;
    private final Queue<Integer> buffer = new LinkedList<>();
    private final Semaphore empty = new Semaphore(1, true); // semaphore for tracking available items in the buffer
    private final Semaphore full = new Semaphore(0, true);  // semaphore for tracking remaining spaces in the buffer

    public BoundedBuffer(int capacity) {
        this.capacity = capacity;
    }

    public synchronized void put(Integer item) throws InterruptedException {
        empty.acquire(); // block until there is a space to insert an element
        if (buffer.size() < capacity) { 
