import java.util.logging.*;
import java.util.concurrent.atomic.*;

public class MyAppThread extends Thread {
    private static final String DEFAULT_NAME = "MyAppThread";

    // AtomicInteger for thread name auto-increment and static logger
    private static final AtomicInteger ai = new AtomicInteger(0);
    private static final Logger log = Logger.getLogger(MyAppThread.class.getName());

    // AtomicCounters for tracking threads created and active
    private static final AtomicLong alCreated = new AtomicLong(0L);
    private static final AtomicLong alAlive = new AtomicLong(1L); // initial thread is considered alive

    private boolean debug;

    public MyAppThread() {
        this.debug = false;
    }

    public MyAppThread(String name) {
        super(name + "-" + ai.incrementAndGet());
        this.debug = true;
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        int numThreads = 6; // Maximum number of threads (including main thread)

        BlockingQueue<MyAppThread> queue = new ArrayBlockingQueue<>(numThreads-1);
        ExecutorService executor = Executors.newFixedThreadPool(5); // Fixed thread pool, no cached pools

        for (int i = 0; i < numThreads; i++) {
            MyAppThread task = new MyAppThread("Custom Thread");
            alCreated.incrementAndGet();

            executor.submit(task);

            while(!queue.offer(task, 5, TimeUnit.SECONDS)) {
                log.severe("Queue full!");
                queue.poll();
            }
        }

        executor.shutdown(); // shut down the executor after all tasks have been submitted
    }

    @Override
    public void run() {
        alAlive.incrementAndGet();
        if (debug) log.info("Thread " + getName() + " started.");

        try {
            Thread.sleep(100); // Simulating a task that takes 0.1 seconds to complete
        } catch (InterruptedException e) {
            log.log(Level.SEVERE, "", e);
        } finally {
            alAlive.decrementAndGet();

            if (debug && !isAlive())
                log.info("Thread " + getName() + " stopped.");
        }
    }

    public static long getCreatedCount() {
        return alCreated.get();
    }

    public static long getActiveCount() {
        return alAlive.get();
    }

