        if (debugLifecycle) {
            logger.log(Level.INFO, "{0} created", getName());
        }

        threadCounter.incrementAndGet();
        try {
            super.run();
        } finally {
            threadCounter.decrementAndGet();

            if (debugLifecycle) {
                logger.log(Level.INFO, "{0} terminated", getName());
            }
        }
    }

