        isCancelled.set(true);  // Cancel the generation process
        future.cancel(true);   // Wait for the task to finish if it hasn't already done so
        executor.shutdown();    // Terminate the executor service

        System.out.println("Prime numbers generated: " + primes);
    }

    private static boolean isPrime(int num) {
        if (num <= 1) return false;
        for (int i = 2; i * i <= num; ++i) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

