/**
* A factorizer with synchronized cache access.
* Avoids using volatile or thread pool to remain JPF-compatible.
*/
public class FactorizerWithCache {
private static OneValueCache cache = new OneValueCache(null, null);

public static BigInteger[] factor(BigInteger n) {
List<BigInteger> factors = new ArrayList<>();
BigInteger i = BigInteger.valueOf(2);

while (i.multiply(i).compareTo(n) <= 0) {
while (n.mod(i).equals(BigInteger.ZERO)) {
factors.add(i);
n = n.divide(i);
}
i = i.add(BigInteger.ONE);
}

if (n.compareTo(BigInteger.ONE) > 0) {
factors.add(n);
}

return factors.toArray(new BigInteger[0]);
}

public static void handleRequest(BigInteger number, int threadId) {
BigInteger[] cachedFactors;

synchronized (FactorizerWithCache.class) {
cachedFactors = cache.getFactors(number);

