    public Iterator<E> iterator() {
        return list.iterator();
    }

    @Override
    public Object[] toArray() {
        return list.toArray();
    }

    @Override
    public <T> T[] toArray(T[] a) {
        return list.toArray(a);
    }

    @Override
    public boolean add(E e) {
        if (cache.putIfAbsent(e, Boolean.TRUE)) { // check if e is already in the map
            return false;
        } else {
            synchronized (this) { // synchronize put operation
                return list.add(e); 
            }
        }
    }

    @Override
    public boolean remove(Object o) {
        synchronized (this) { // synchronize remove operation
            Boolean removed = cache.remove(o);
            if (removed == null) return list.remove(o);
            return true;
        }
    }

    @Override
    public boolean containsAll(Collection<?> c) {
        return list.containsAll(c);
    }

    @Override
    public boolean addAll(int index, Collection<? extends E> c) {
        synchronized (this) { // synchronize addAll operation
            Boolean added = cache.putIfAbsent("addAll", Boolean.TRUE); 
            if (added == null) return list.addAll(index, c);
            return false;
        }
    }

    @Override
    public boolean removeAll(Collection<?> c) {
        synchronized (this) { // synchronize removeAll operation
            Iterator<E> iterator = this.iterator();
            while (iterator.hasNext()) {
                if (c.contains(iterator.next())) {
                    iterator.remove(); 
                }
            }
            return false;
        }
    }

    @Override
    public boolean retainAll(Collection<?> c) {
        synchronized (this) { // synchronize retainAll operation
            Iterator<E> iterator = this.iterator();
            while (iterator.hasNext()) {
                if (!c.contains(iterator.next())) {
                    iterator.remove(); 
                }
            }
            return false;
        }
    }

    @Override
    public void clear() {
        synchronized (this) { // synchronize clear operation
            cache.clear();
            list.clear();
        }
    }

    @Override
    public E get(int index) {
        return list.get(index);
    }

    @Override
    public E set(int index, E element) {
        synchronized (this) { // synchronize set operation
            if (!cache.containsKey(element)) { 
                cache.put(list.get(index), Boolean.TRUE);
            }
            return list.set(index, element); 
        }
    }

    @Override
    public void add(int index, E element) {
        synchronized (this) { // synchronize add operation
            if (!cache.containsKey(element)) { 
                cache.putIfAbsent(element, Boolean.TRUE);
            }
            list.add(index, element); 
        }
    }

    @Override
    public E remove(int index) {
        synchronized (this) { // synchronize remove operation
            E removed = cache.remove(list.get(index));
            if (removed == null) return list.remove(index);
            return removed; 
        }
    }
}

