public class NonBlockingStack<T> implements Supplier<Optional<T>> {
    private final AtomicReference<Node> top = new AtomicReference<>();

    @Override
    public Optional<T> get() {
        return top.get().map(this::cast);
    }

    private <U extends T> U cast(Node node) {
        return (U) node.item;
    }

    void push(int item) {
        Node newHead = new Node(item, null);

        while(true){
            Node oldHead = top.get();

            newHead.next = oldHead;

            if (top.compareAndSet(oldHead, newHead)) break;
        }
    }

    Optional<Integer> pop() {
        while(true){
            Node oldHead = top.get();

            if(oldHead == null) return Optional.empty();

            int item = oldHead.item;

            if (top.compareAndSet(oldHead, oldHead.next)) {
                return Optional.of(item);
            }
        }
    }
