public class Stack<T> {
    private volatile Node<T> top;

    public boolean push(T item) {
        Node<T> newNode = new Node<>(item);
        for (;;) {
            Node<T> currentTop = this.top;
            newNode.next.set(currentTop);

            if (this.top == currentTop) { 
                // CAS is not successful, so we need to retry
                continue;
            }
            if (!this.top.next.compareAndSet(currentTop, newNode)) {
                throw new IllegalStateException("Stack changed by another thread");
            }

            return true;  // CAS was successful
        }
    }

    public T pop() {
        for (;;) {
            Node<T> currentTop = this.top;
            if (currentTop == null) {
                throw new NoSuchElementException("Stack is empty");
            }

            // If stack was changed by another thread, retry
            if (this.top != currentTop) {
                continue; 
            }

            Node<T> oldTop = this.top;
            T item = currentTop.item;
            if (currentTop == oldTop && this.top.next.compareAndSet(oldTop, currentTop.next())) {
                return item; // CAS was successful
            } else {
                throw new IllegalStateException("Stack changed by another thread");
            } 
        }
    }
}

