import java.util.concurrent.atomic.*;
import java.util.stream.*;

public class DelegatingVehicleTracker {
    private final ConcurrentHashMap<String, String> vehicles = new ConcurrentHashMap<>();
    private final Map<String, String> view;
    private final AtomicBoolean updated = new AtomicBoolean(false);
    private final ExecutorService executor = Executors.newFixedThreadPool(3); // max of 3 threads

    public DelegatingVehicleTracker() {
        vehicles.put("vehicleId1", "location1");
        vehicles.put("vehicleId2", "location2");
        view = Collections.unmodifiableMap(vehicles);
    }

    public String getLocation(String id) throws InterruptedException {
        updated.set(true);
        executor.execute(() -> updated.compareAndSet(true, false));
        return vehicles.get(id);
    }

    public void setLocation(String id, String location) throws InterruptedException {
        if (!vehicles.containsKey(id)) throw new IllegalArgumentException();
        vehicles.put(id, location);
        updated.set(true);
        executor.execute(() -> updated.compareAndSet(true, false));
    }

    public Map<String, String> getAllLocations() {
        return view;
    }

