import java.util.*;
import java.util.concurrent.*;
import java.lang.Enum;

// Enum for animal species
enum Species {
    LION, TIGER, BEAR, ELEPHANT;
}

// Enum for gender
enum Gender {
    MALE, FEMALE;
}

// Class to represent an individual Animal
class Animal{
    private final Species species;
    private final Gender gender;

    public Animal(Species species, Gender gender){
        this.species = species;
        this.gender = gender;
    }

    public boolean isCompatibleWith(Animal other) {
        return (this.species == other.species && this.gender != other.gender);
    }
}

// Class to represent pairs of animals
class AnimalPair{
    private final Animal animal1;
    private final Animal animal2;

    public AnimalPair(Animal animal1, Animal animal2){
        this.animal1 = animal1;
        this.animal2 = animal2;
    }
}

// Class to represent the Ark
class Ark{
    // Use a fixed size thread pool to prevent unbounded thread creation
    private final ExecutorService executor = Executors.newFixedThreadPool(3);

    public int loadTheArk(Collection<Animal> animals) {
        // Sort the animals by species and gender
        Collections.sort(animals, new Comparator<Animal>() {
            @Override
            public int compare(Animal o1, Animal o2) {
                if (o1.species == o2.species) return o1.gender != o2.gender ? 0 : 1;
                else return o1.species.compareTo(o2.species);
            }
        });

        int pairs = 0;
        for (Animal current : animals) {
            Future<AnimalPair> future = executor.submit(() -> {
                // Check if there is a compatible animal to pair with, within the same species and opposite gender
                for (Animal other : animals) {
                    if(current.isCompatibleWith(other)) {
                        return new AnimalPair(current, other);
                    }
                }
                return null; 
            });

            // If a compatible animal pair was found, increase the pair count and break out of the loop
            if (future.get() != null) {
                pairs++;
                break;
            }
        }

        executor.shutdown(); 
        return pairs; 
    }
}

public class Main{

    public static void main(String[] args){
        ArrayList<Animal> animals = new ArrayList<>();
        animals.add(new Animal(Species.LION, Gender.MALE));
        animals.add(new Animal(Species.BEAR, Gender.FEMALE));

        Ark ark = new Ark();
        System.out.println("Pairs: " + ark.loadTheArk(animals)); 
    }
}

import java.util.*;
import java.util.concurrent.*;

enum Species {
    DOG,
    CAT,
    BIRD;
}

class Animal implements Comparable<Animal> {
    private final Species species;
    private final Gender gender;

    Animal(Species species, Gender gender) {
        this.species = species;
        this.gender = gender;
    }

    public Species getSpecies() { return species; }
    public Gender getGender() { return gender; }

    @Override
    public int compareTo(Animal o) {
        if (species.equals(o.getSpecies())) {
            return -1 * gender.compareTo(o.getGender());
        } else {
            return species.compareTo(o.getSpecies());
        }
    }
}

enum Gender {
    MALE, FEMALE;
}

class Pair {
    private final Animal first;
    private final Animal second;

    Pair(Animal first, Animal second) {
        this.first = first;
        this.second = second;
    }

    public boolean isValid() {
        return (first.getSpecies().equals(second.getSpecies()) && !first.getGender().equals(second.getGender()));
    }
}

class Ark {
    private final BlockingQueue<Pair> pairQueue = new LinkedBlockingQueue<>();

    public void loadTheArk(Collection<Animal> animals) {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        for (Animal a : animals) {
            for (Animal b : animals) {
                if (a != b && a.compareTo(b) < 0) {
                    Pair pair = new Pair(a, b);
                    executor.execute(() -> pairQueue.offer(pair));
                }
            }
        }

        for (int i = 0; i < pairQueue.size(); i++) {
            Pair pair = pairQueue.poll();

            if (pair != null && pair.isValid()) {
                System.out.println(pair);

                // If we've found a valid pair, stop the program
                break;
            }
        }

        executor.shutdown();
    }
}

