    public static void main(String[] args) {
        ArrayList<Animal> animals = new ArrayList<>();
        animals.add(new Animal(Species.DOG, Gender.MALE));
        animals.add(new Animal(Species.CAT, Gender.FEMALE));

        Ark ark = new Ark();
        ark.loadTheArk(animals);
    }
}

