import java.util.*;
import java.util.concurrent.*;

public class BoundedHashSet<T> {
    private Set<T> set;
    private Semaphore semaphore;

    public BoundedHashSet(int bound) {
        this.set = Collections.synchronizedSet(new HashSet<>());
        this.semaphore = new Semaphore(bound, true);
    }

    // This method tries to acquire a permit from the semaphore before adding an element. 
    public boolean add(T o) {
        try {
            if (!this.semaphore.tryAcquire()) return false;
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Propagate the interruption
            return false;
        }

        boolean added = this.set.add(o);
        if (!added) this.semaphore.release();
        return added;
    }

    public boolean remove(Object o) {
        // This method removes the element from the set and releases a permit if the removal was successful. 
        boolean removed = this.set.remove(o);

        if (removed && !this.semaphore.tryRelease()) Thread.currentThread().interrupt();
        return removed;
    }
}
public static void main(String[] args) {
    final int NUM_THREADS = 5, BOUND = 10; // Maximum number of elements and bound for semaphore.

    ExecutorService executorService = Executors.newFixedThreadPool(NUM_THREADS);
    BoundedHashSet<Integer> boundedHashSet = new BoundedHashSet<>(BOUND);

    Random random = new Random();
    for (int i = 0; i < BOUND * NUM_THREADS; i++) {
        final int value = random.nextInt(100);

        executorService.execute(() -> boundedHashSet.add(value)); // Adding elements to the BoundedHashSet.
    }

    executorService.shutdown();
}

