class BoundedHashSet<T> {
    private final Semaphore semaphore;
    private final Set<T> set;

    public BoundedHashSet(int bound) {
        this.semaphore = new Semaphore(bound); // Initializes semaphore with given bound
        this.set = Collections.synchronizedSet(new HashSet<>());  // Creates a synchronized set
    }

    public void add(T o) {
        try {
            if (semaphore.tryAcquire()) {
                set.add(o);
            } else {
                semaphore.release();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Restores interrupted status in case of interruption
        }
    }

    public boolean remove(Object o) {
        if (!set.contains(o)) return false;

        boolean removed = set.remove(o);
        if (removed) semaphore.release();
        return removed;
    }

    public Set<T> getSet() {
        return set;
    }
}

