public class Main {
    private static volatile boolean cancellationState = false; // shared variable to manage thread cancellation state
    private static List<Integer> primes = new ArrayList<>(); 

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        final int targetCount = 10;
        ExecutorService executor = Executors.newFixedThreadPool(targetCount);

        Future<?>[] futures = new Future[targetCount];
        for (int i=2; i<30 && primes.size() < targetCount; i++) { // only check up to 30, as we're looking for prime numbers
            futures[i-2] = executor.submit(() -> {
                if (!cancellationState) {
                    if (isPrime(i)) {
                        primes.add(i);
                    }
                } else {
                    System.out.println("Cancellation detected, stopping execution");
                    executor.shutdownNow(); // cancel all remaining tasks
                }
            }); 
