    private final int limit;

    public PrimeProducer(String name, int limit, BlockingQueue<Integer> queue) {
        super(name);
        this.queue = queue;
        this.limit = limit;
    }

    @Override
    public void run() {
        for (int i = 2; i < limit; ++i) {
            if (isPrime(i)) {
                try {
                    queue.put(i);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt(); // Restore interrupted status
                    return;
                }
            }
        }
    }

    private boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        } else if (n <= 3) {
            return true;
        } else if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }

        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}

