public class SequentialAndParallel {
    private ExecutorService executor = Executors.newFixedThreadPool(2);  // Fixed thread pool with max of 2 threads

    public interface Element<T> { T process(); }  // Define the Element interface
    public interface Node<T> extends Element<List<T>> { List<Node<T>> getChildren(); void setChildResults(List<T> results); }  // Define the Node interface

    private class ProcessElement implements Runnable {
        private final Element<?> element;

        public ProcessElement(Element<?> element) { this.element = element; }

        @Override public void run() { System.out.println("Result: " + element.process()); }  // Implement sequential processing
    }

    private class ProcessNode implements Runnable {
        private final Node<?> node; 

        public ProcessNode(Node<?> node) { this.node = node; }

        @Override public void run() { node.setChildResults(processChildrenInParallel(node.getChildren())); }  // Implement parallel processing
    }

    private List<T> processChildrenInParallel(List<Node<T>> children) { 
        return children.stream()
            .map(child -> executor.submit(() -> child.process()))  // Submit each element for parallel processing via ExecutorService
            .flatMap(future -> { try { return Arrays.asList(future.get()); } catch (InterruptedException | ExecutionException e) { throw new RuntimeException(e); } })
            .collect(Collectors.toList());  // Collect results in a thread-safe manner
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        SequentialAndParallel s = new SequentialAndParallel();

        Node<Integer> rootNode = new Node<>() {
            @Override public List<Node<Integer>> getChildren() { return Arrays.asList(new ChildNode(), new ChildNode()); }

            @Override public void setChildResults(List<Integer> results) {  // Set child results in thread-safe way
                Collections.synchronizedList(Arrays.asList()).addAll(results);
            }};
        Node<Integer> childNode = new ChildNode();

        s.executor.execute(new ProcessElement(() -> rootNode.process()));  // Process elements sequentially (root node)
        s.executor.submit(new ProcessNode(childNode));  // Process elements in parallel (each child node)
    }
}

