    @Override
    public void run() {
        try {
            // Use an ExecutorService to process the elements in parallel.
            ExecutorService executorService = Executors.newFixedThreadPool(2); 

            Queue<Node<?>> nodesToProcess = new LinkedList<>();
            nodesToProcess.add(root);

            while (!nodesToProcess.isEmpty()) {
                Node<?> node = nodesToProcess.poll();

                // Submit the task to be processed by an ExecutorService thread.
                Future<Integer> futureResult = executorService.submit(() -> (Integer)node.process()); 

                // Collect and process child nodes in a thread-safe manner.
                for (Node<?> child : node.getChildren()) {
                    nodesToProcess.add(child);
                }

                System.out.println("Computed result of " + node + ": " + futureResult.get()); 
            }

            executorService.shutdown();
        } catch (InterruptedException | ExecutionException e) {
            Thread.currentThread().interrupt(); // Restore interrupted status.
