import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

public class ReadWriteMap<K, V> {
    private Map<K, V> map;
    private ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public ReadWriteMap(Map<K, V> map) {
        this.map = map;
    }

    // Acquiring read lock and releasing it after the operation is done
    private void acquireAndReleaseReadLock() {
        try {
            lock.readLock().lock();
        } finally {
            if (lock.isHeldByCurrentThread()) {
                lock.readLock().unlock();
            }
        }
    }

    // Acquiring write lock and releasing it after the operation is done
    private void acquireAndReleaseWriteLock() {
        try {
            lock.writeLock().lock();
        } finally {
            if (lock.isHeldByCurrentThread()) {
                lock.writeLock().unlock();
            }
        }
    }

    public V get(K key) {
        acquireAndReleaseReadLock();
        return map.get(key);
    }

    public boolean containsKey(K key) {
        acquireAndReleaseReadLock();
        return map.containsKey(key);
    }

    public void put(K key, V value) {
        acquireAndReleaseWriteLock();
        map.put(key, value);
    }

    public void remove(K key) {
        acquireAndReleaseWriteLock();
        map.remove(key);
    }

    public int size() {
        acquireAndReleaseReadLock();
        return map.size();
    }

    public boolean isEmpty() {
        acquireAndReleaseReadLock();
        return map.isEmpty();
    }

    public boolean containsValue(V value) {
        acquireAndReleaseReadLock();
        return map.containsValue(value);
    }

    // For multi threaded test cases
    private static ExecutorService executor = Executors.newFixedThreadPool(3);

    public static void main(String[] args) throws InterruptedException {
        Map<Integer, String> myMap = new HashMap<>();
