                for (int i = 0; i < 5; i++) {
                    readWriteMap.size();
                }
            }
        }, new Runnable() {
            @Override
            public void run() {
                System.out.println("Reading at thread: " + Thread.currentThread().getId());
                for (int i = 0; i < 5; i++) {
                    readWriteMap.isEmpty();
                }
            }
        }, new Runnable() {
