                System.out.println("Reading at thread: " + Thread.currentThread().getId());
                for (int i = 0; i < 5; i++) {
                    readWriteMap.containsValue("one");
                }
            }));

        // Testing writing operations concurrently
        executor.invokeAll(Arrays.asList(new Runnable() {
            @Override
            public void run() {
                System.out.println("Writing at thread: " + Thread.currentThread().getId());
                for (int i = 0; i < 5; i++) {
