import java.util.*;
import java.util.concurrent.locks.*;

public class ReadWriteMap {

    private final Map<String, String> map;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public ReadWriteMap(final Map<String, String> map) {
        this.map = map;
    }

    // Read operation methods

    public String get(String key) throws InterruptedException {
        lock.readLock().lockInterruptibly();

        try {
            return map.get(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public int size() throws InterruptedException {
        lock.readLock().lockInterruptibly();

        try {
            return map.size();
        } finally {
            lock.readLock().unlock();
        }
    }

    // Write operation methods

    public void put(String key, String value) throws InterruptedException {
        lock.writeLock().lockInterruptibly();

        try {
            map.put(key, value);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void remove(String key) throws InterruptedException {
        lock.writeLock().lockInterruptibly();

        try {
            map.remove(key);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void putAll(Map<String, String> m) throws InterruptedException {
        lock.writeLock().lockInterruptibly();

        try {
            map.putAll(m);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void clear() throws InterruptedException {
        lock.writeLock().lockInterruptibly();

        try {
            map.clear();
        } finally {
            lock.writeLock().unlock();
        }
    }
}

