public void run() {
for (int i = 0; i < 3; i++) {
String val = rwMap.get("key" + i);
if (val != null) {
System.out.println("Reader2 read: " + val);
}
}
}
});

writer.start();
reader1.start();
reader2.start();

writer.join();
reader1.join();
reader2.join();

System.out.println("Final size: " + rwMap.size());
}
}

